} catch (_) {
  _candidateActionFeedback = const WorkbenchCandidateActionFeedback(
    state: WorkbenchCandidateActionState.failed,
    message: '候选采纳未完成，未将缓存正文写入编辑器。请查看运行记录后重试。',
